// Author: MiYu. Script text tags retain actual state, lifetime and world position for the game view.
#include "session.h"
#include "snapshot_codec.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <set>

namespace war3 {
namespace {
float textTagReal(jass::Value value) {float v=std::bit_cast<float>(value.bits);if(!std::isfinite(v) || std::abs(v)>1000000000.f)throw std::runtime_error("Invalid text tag value");return v;}
std::uint8_t textTagByte(jass::Value value) {return std::uint8_t(std::clamp(std::bit_cast<std::int32_t>(value.bits),0,255));}
}
Bytes ScriptSession::encodeTextTags(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=40u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Text tag snapshot requires a quiescent local session");std::vector<std::pair<std::uint32_t,std::uint32_t>> handles;std::set<std::uint32_t> stable;size_t liveCount=0;for(size_t i=0;i<objects_.size();++i)if(objects_[i].kind==NativeKind::TextTag){auto id=handleBase+std::uint32_t(i),saved=encodeHandle?encodeHandle("texttag",id):0;if(!saved || !stable.insert(saved).second)throw std::runtime_error("Invalid text tag identity mapping");handles.emplace_back(saved,id);if(objects_[i].alive)++liveCount;}if(handles.size()>65536 || liveCount>8192 || liveCount!=textTags_.size())throw std::runtime_error("Text tag identity budget or state differs");std::sort(handles.begin(),handles.end());SnapshotWriter out(budget-64);out.u32(tag("STTX"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.size(handles.size());for(auto [saved,id]:handles){auto& object=objects_[id-handleBase];out.u32(saved);out.u32(object.alive?1:0);if(!object.alive)continue;auto value=std::get<std::shared_ptr<ScriptTextTag>>(object.state);if(!value || !textTags_.contains(id) || textTags_.at(id)!=value)throw std::runtime_error("Invalid text tag state");out.text(value->text,4096);for(auto v:{value->x,value->y,value->z,value->height,value->vx,value->vy,value->age,value->lifespan,value->fadepoint}){if(!std::isfinite(v))throw std::runtime_error("Invalid text tag value");out.u32(std::bit_cast<std::uint32_t>(v));}for(auto color:value->color)out.u32(color);for(bool flag:{value->visible,value->suspended,value->permanent})out.u32(flag?1:0);}return sealSnapshot(out.finish(),budget);
}
std::map<std::uint32_t,std::uint32_t> ScriptSession::rebuildTextTags(std::span<const std::uint8_t> bytes) {
    constexpr size_t budget=40u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || textTagsRebuilt_ || !textTags_.empty() || std::any_of(objects_.begin(),objects_.end(),[](auto& object){return object.kind==NativeKind::TextTag;}) || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Text tag rebuild requires a fresh quiescent session");Binary in(openSnapshot(bytes,budget));in.expect(tag("STTX"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Text tag snapshot map, clock or version differs");auto count=in.count(8,65536);if(objects_.size()>1048576 || count>1048576-objects_.size())throw std::runtime_error("Session native object budget exceeded");std::vector<Object> pending;pending.reserve(count);std::map<std::uint32_t,std::uint32_t> result;std::map<std::uint32_t,std::shared_ptr<ScriptTextTag>> tags;for(unsigned i=0;i<count;++i){auto saved=in.u32(),live=in.u32(),id=handleBase+std::uint32_t(objects_.size()+pending.size());if(!saved || live>1 || !result.emplace(saved,id).second)throw std::runtime_error("Invalid text tag identity");if(!live){pending.push_back(Object{NativeKind::TextTag,false,std::monostate{}});continue;}if(tags.size()>=8192)throw std::runtime_error("Text tag budget exceeded");auto value=std::make_shared<ScriptTextTag>();value->text=snapshotText(in,4096);for(auto field:{&value->x,&value->y,&value->z,&value->height,&value->vx,&value->vy,&value->age,&value->lifespan,&value->fadepoint}){*field=std::bit_cast<float>(in.u32());if(!std::isfinite(*field))throw std::runtime_error("Invalid text tag value");}if(value->height<0 || value->age<0 || value->lifespan<0 || value->fadepoint<0)throw std::runtime_error("Invalid text tag lifetime");for(auto& color:value->color){auto byte=in.u32();if(byte>255)throw std::runtime_error("Invalid text tag color");color=std::uint8_t(byte);}for(auto field:{&value->visible,&value->suspended,&value->permanent}){auto flag=in.u32();if(flag>1)throw std::runtime_error("Invalid text tag flag");*field=flag!=0;}tags.emplace(id,value);pending.push_back(Object{NativeKind::TextTag,true,std::move(value)});}in.finish();objects_.reserve(objects_.size()+pending.size());for(auto& object:pending)objects_.push_back(std::move(object));textTags_.swap(tags);textTagsRebuilt_=true;return result;
}
void ScriptSession::textTagsTick(double delta) {
    std::vector<std::uint32_t> expired;for(auto& [id,tag]:textTags_){if(tag->suspended)continue;tag->age+=float(delta);tag->x+=tag->vx*float(delta)*4096.f;tag->y+=tag->vy*float(delta)*4096.f;if(!tag->permanent && tag->age>=tag->lifespan)expired.push_back(id);}for(auto id:expired){textTags_.erase(id);destroy(runtime_.handle("texttag",id),NativeKind::TextTag);}
}
void ScriptSession::bindTextTagNatives() {
    auto get=[this](jass::Value h)->std::shared_ptr<ScriptTextTag>{if(!h.bits)return {};return std::get<std::shared_ptr<ScriptTextTag>>(object(h,NativeKind::TextTag).state);};
    bind("CreateTextTag","texttag",{},[this](auto&,auto){if(textTags_.size()>=8192)throw std::runtime_error("Text tag instance budget exceeded");auto h=create(NativeKind::TextTag);textTags_[h.bits]=std::get<std::shared_ptr<ScriptTextTag>>(object(h,NativeKind::TextTag).state);return h;});
    bind("DestroyTextTag","nothing",{"texttag"},[this](auto& vm,auto a){if(a[0].bits){object(a[0],NativeKind::TextTag);textTags_.erase(a[0].bits);destroy(a[0],NativeKind::TextTag);}return vm.nothing();});
    bind("SetTextTagText","nothing",{"texttag","string","real"},[get](auto& vm,auto a){if(auto tag=get(a[0])){auto value=a[1].text?*a[1].text:std::string{};if(value.size()>4096)throw std::runtime_error("Text tag text exceeds budget");tag->text=std::move(value);tag->height=std::max(0.f,textTagReal(a[2]));}return vm.nothing();});
    bind("SetTextTagPos","nothing",{"texttag","real","real","real"},[this,get](auto& vm,auto a){if(auto tag=get(a[0])){tag->x=textTagReal(a[1]);tag->y=textTagReal(a[2]);auto z=textTagReal(a[3]);WorldPoint p{jass::Real::fromBits(a[1].bits),jass::Real::fromBits(a[2].bits)};tag->z=requireWorld().height(p)+z;}return vm.nothing();});
    bind("SetTextTagPosUnit","nothing",{"texttag","unit","real"},[this,get](auto& vm,auto a){if(auto tag=get(a[0]);tag && a[1].bits){auto u=std::get<std::shared_ptr<UnitState>>(object(a[1],NativeKind::Unit).state);tag->x=std::bit_cast<float>(u->x.bits());tag->y=std::bit_cast<float>(u->y.bits());tag->z=requireWorld().height({u->x,u->y})+u->displayFlyHeight()+textTagReal(a[2]);}return vm.nothing();});
    bind("SetTextTagColor","nothing",{"texttag","integer","integer","integer","integer"},[get](auto& vm,auto a){if(auto tag=get(a[0]))for(unsigned i=0;i<4;++i)tag->color[i]=textTagByte(a[i+1]);return vm.nothing();});
    bind("SetTextTagVelocity","nothing",{"texttag","real","real"},[get](auto& vm,auto a){if(auto tag=get(a[0])){tag->vx=textTagReal(a[1]);tag->vy=textTagReal(a[2]);}return vm.nothing();});
    bind("SetTextTagVisibility","nothing",{"texttag","boolean"},[get](auto& vm,auto a){if(auto tag=get(a[0]))tag->visible=a[1].bits!=0;return vm.nothing();});
    bind("SetTextTagSuspended","nothing",{"texttag","boolean"},[get](auto& vm,auto a){if(auto tag=get(a[0]))tag->suspended=a[1].bits!=0;return vm.nothing();});
    bind("SetTextTagPermanent","nothing",{"texttag","boolean"},[get](auto& vm,auto a){if(auto tag=get(a[0]))tag->permanent=a[1].bits!=0;return vm.nothing();});
    bind("SetTextTagAge","nothing",{"texttag","real"},[get](auto& vm,auto a){if(auto tag=get(a[0]))tag->age=std::max(0.f,textTagReal(a[1]));return vm.nothing();});
    bind("SetTextTagLifespan","nothing",{"texttag","real"},[get](auto& vm,auto a){if(auto tag=get(a[0]))tag->lifespan=std::max(0.f,textTagReal(a[1]));return vm.nothing();});
    bind("SetTextTagFadepoint","nothing",{"texttag","real"},[get](auto& vm,auto a){if(auto tag=get(a[0]))tag->fadepoint=std::max(0.f,textTagReal(a[1]));return vm.nothing();});
}
}
